import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第三册：培养技能 · Lesson 60 Too early and too late","description":"学习 时间从句与将来表达整合，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 60 Too early and too late","description":"学习 时间从句与将来表达整合，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 时间从句与将来表达整合，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 59 Collecting","link":"/life/english/new-concept/book-3/unit-03/lesson-059"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 59 Collecting","link":"/life/english/new-concept/book-3/unit-03/lesson-059"},"next":false},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-03/lesson-060.md","filePath":"life/english/new-concept/book-3/unit-03/lesson-060.md"}'),l={name:"life/english/new-concept/book-3/unit-03/lesson-060.md"};function i(r,e,s,h,d,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第三册-培养技能-·-lesson-60-too-early-and-too-late" tabindex="-1">第三册：培养技能 · Lesson 60 Too early and too late <a class="header-anchor" href="#第三册-培养技能-·-lesson-60-too-early-and-too-late" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 60 Too early and too late&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>以准时、等待和文化习惯为全册收束，练习整合时间、礼貌与信息明确性。太早和太晚都需要参照具体约定，不能脱离活动性质一概判断。学习时间从句中的时态、just as 的同步关系以及 by the time 的完成视角，写出不含糊的赴约说明。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>punctual</td><td>/ˈpʌŋktʃuəl/</td><td>adj.</td><td>准时的</td><td>be punctual</td></tr><tr><td>appointment</td><td>/əˈpɔɪntmənt/</td><td>n.</td><td>预约</td><td>keep an appointment</td></tr><tr><td>arrival</td><td>/əˈraɪvəl/</td><td>n.</td><td>到达</td><td>the arrival time</td></tr><tr><td>consideration</td><td>/kənˌsɪdəˈreɪʃən/</td><td>n.</td><td>体谅</td><td>show consideration</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>just as — 恰好在……时，也有比较用法，需看语境</li><li>ahead of time — 提前于安排时间</li></ul><h2 id="语法讲解-时间从句与将来表达整合" tabindex="-1">语法讲解：时间从句与将来表达整合 <a class="header-anchor" href="#语法讲解-时间从句与将来表达整合" aria-label="Permalink to &quot;语法讲解：时间从句与将来表达整合&quot;">​</a></h2><p>when、as soon as、until、before 等引导普通未来时间从句时，通常用现在时而不用 will；若要强调先完成，也可用现在完成时，如 after you have checked in。just as 常表示两个动作恰好同时，by the time 则强调到某时已有某结果。when 引导名词性间接疑问时可以出现 will，如 I don&#39;t know when he will arrive，不能把时间从句规则扩展到所有 when。赴约语言要同时说明活动开始时间和期待到达时间，减少“准时”的解释差异。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Please call me when you arrive, and I will meet you at the side entrance.</p></blockquote><p>请在到达时给我打电话，我会到侧门接你。</p><p>when you arrive 是未来时间从句，用现在时；主句后半用 will 表示响应行动。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>I don&#39;t know when he arrives tomorrow 与 when he will arrive tomorrow 可依语境不同；间接疑问并不受“时间从句不能用 will”的简单规则限制。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>读 starts at ten 与 fifteen minutes early 后算出到达时间；再遮住文本复述联系办法，检查 when 从句是否误加 will。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The workshop starts at ten, but please arrive fifteen minutes early. When you reach the building, send me a message. I will meet you by the blue sign beside the side entrance.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用三句写一条完整赴约说明，包含活动时间、到达要求和联系办法。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>时间要求具体，when 从句与 will 主句正确配合，标志物进一步减少地点歧义。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填空：I will wait until you ___.（return/will return）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> return</p><p><strong>解析：</strong> 普通未来时间从句用现在时。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>I don&#39;t know when she will arrive 是否一定错误？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不是。</p><p><strong>解析：</strong> when 从句在此是间接疑问，作 know 的宾语。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>例句约定在哪个入口见面？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 侧门。</p><p><strong>解析：</strong> at the side entrance 给出明确地点。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：时间从句与将来表达整合。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-059">上一课</a> · <a href="/life/english/new-concept/book-3/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/review">全册自测</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(l,[["render",i]]);export{p as __pageData,b as default};
